?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BDC Live Display</title><style>html,body{margin:0;width:100%;height:100%;background:#000;overflow:hidden}iframe{display:block;width:100vw;height:100vh;border:0;background:#000}.fx{pointer-events:none;position:fixed;inset:0;z-index:10;display:none;align-items:center;justify-content:center;font-family:Arial;color:#fff;text-align:center}.fx.on{display:flex}.fx.drumroll{background:radial-gradient(circle,rgba(160,20,50,.55),rgba(0,0,0,.15));font-size:clamp(45px,7vw,150px);font-weight:900;animation:pulse .45s infinite alternate}.particle{position:absolute;font-size:clamp(24px,4vw,70px);animation:fall 2.8s linear forwards}@keyframes pulse{to{transform:scale(1.08);text-shadow:0 0 40px #ffcf45}}@keyframes fall{from{transform:translateY(-15vh) rotate(0)}to{transform:translateY(115vh) rotate(720deg)}}</style></head><body><iframe id="feed" title="BDC Live Display Feed" allow="fullscreen"></iframe><div id="fx" class="fx"></div><script>
const token=<?=json_encode($token)?>,feed=document.querySelector('#feed'),fx=document.querySelector('#fx');let fingerprint='',effectFingerprint='',timerFingerprint='',pageTimer=null,busy=false;
function effect(s){const key=[s.effect_type,s.effect_version].join('|');if(key===effectFingerprint)return;effectFingerprint=key;fx.className='fx';fx.innerHTML='';if(!s.effect_type)return;fx.classList.add('on',s.effect_type);if(s.effect_type==='drumroll'){fx.textContent='🥁 RANDOM MATCH 🥁';return;}const icon=s.effect_type==='fireworks'?'🎆':'🎉';for(let i=0;i<45;i++){const p=document.createElement('span');p.className='particle';p.textContent=icon;p.style.left=Math.random()*100+'vw';p.style.animationDelay=Math.random()*1.4+'s';fx.appendChild(p)}setTimeout(()=>{fx.className='fx';fx.innerHTML=''},4200)}
function load(s){effect(s);const fp=[s.state_version,s.data_version||0,s.screen_type,s.round_id,s.page_number,s.reveal_place].join('|');if(fp!==fingerprint){fingerprint=fp;const endpoint=s.screen_type==='winners'&&!s.reveal_place?'podium-ready.php':s.screen_type==='final_results'?'final-relative-placement.php':'feed.php';feed.src=endpoint+'?token='+encodeURIComponent(token)+'&v='+encodeURIComponent(fp)+'&_='+Date.now()}const tf=[s.auto_page,s.page_delay_seconds,s.total_pages,s.screen_type].join('|');if(tf===timerFingerprint)return;timerFingerprint=tf;clearInterval(pageTimer);if(!s.loop_enabled&&s.auto_page&&s.total_pages>1&&['competitors','callbacks','finalists'].includes(s.screen_type))pageTimer=setInterval(async()=>{try{await fetch('advance.php?token='+encodeURIComponent(token),{method:'POST',cache:'no-store'});await tick()}catch(e){}},Number(s.page_delay_seconds)*1000)}
async function tick(){if(busy)return;busy=true;try{const r=await fetch('state.php?token='+encodeURIComponent(token)+'&_='+Date.now(),{cache:'no-store'}),s=await r.json();if(s&&s.ok)load(s)}catch(e){}finally{busy=false}}tick();setInterval(tick,700);
</script></body></html>
